quiz.answer:
const lines = require("fs").readFileSync(0, "utf8").split("\n").filter((l) => l.trim() !== "");
const items = lines.map((line) => {
  const [name, stock, price] = line.split(",");
  return { name: name.trim(), stock: Number(stock), price: Number(price) };
});

const labels = items
  .filter((item) => item.stock >= 1)
  .map((item) => `${item.name}: ${Math.round(item.price * 1.1)}円`);

if (labels.length === 0) {
  console.log("在庫なし");
} else {
  console.log(labels.join("\n"));
}

quiz.question:
次のコードについて、① 分割代入の行が何をしているか、② import / export の関係、の 2 点を何も見ずに説明してください(150〜300 字)。

```javascript
// format.js
export function label(user) {
  const { name, age } = user;
  return `${name}(${age}歳)`;
}
```

```javascript
// main.js
import { label } from "./format.js";
console.log(label({ name: "佐藤", age: 28 }));
```
